import React from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';

const PetCard = () => {
  return (
    <div className="card" style={{ width: '18rem' }}>
      <img src="image.png" className="card-img-top" alt="Pitter" />
      <div className="card-body">
        <h5 className="card-title">Pitter</h5>
        <p className="card-text">
          <strong>Location:</strong> California, USA<br />
          <strong>Gender:</strong> Male<br />
          <strong>Breed:</strong> Pit Bull<br />
          <strong>Age:</strong> 5 years<br />
          <strong>Size:</strong> Large<br />
          Pitter is a friendly, playful, smart male dog. Only adopted to a home...
        </p>
        <a href="#" className="btn btn-primary">More Info</a>
      </div>
    </div>
  );
};

export default PetCard;
